INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist 192.168.1.0 bei /24 die Netzwerkadresse?', 2, '[{"text": "Ja", "correct": true, "because": "Erste Adresse im Bereich"}, {"text": "Nein", "correct": false, "because": "Korrekte Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Broadcastadresse hat 192.168.1.0/24?', 3, '[{"text": "192.168.1.255", "correct": true, "because": "Letzte Adresse bei /24"}, {"text": "192.168.1.254", "correct": false, "because": "Vorletzte Adresse"}, {"text": "192.168.2.0", "correct": false, "because": "Nächstes Netz"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 192.168.1.0/24 hat 256 Adressen. b) Es ist ein öffentliches Netz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist privat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Ausgangsadresse 192.168.1.0/24?', 4, '[{"text": "Netzwerkmaske", "correct": false, "because": "Definiert Bereich"}, {"text": "Inkrement", "correct": false, "because": "Bestimmt Subnetze"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.0/24 254 nutzbare Hosts hat?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-24) - 2 = 254"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Adresse folgt auf 192.168.1.0 als erste nutzbare bei /24?', 3, '[{"text": "192.168.1.1", "correct": true, "because": "Nach Netzwerkadresse"}, {"text": "192.168.1.0", "correct": false, "because": "Netzwerkadresse"}, {"text": "192.168.1.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat 192.168.1.0/24?', 5, '[{"text": "Privat", "correct": true, "because": "192.168-Bereich"}, {"text": "256 Adressen", "correct": true, "because": "2^8"}, {"text": "Öffentlich", "correct": false, "because": "Nicht routbar"}, {"text": "16 Subnetze", "correct": false, "because": "Erst bei Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 192.168.1.0/24 hat 255 nutzbare Hosts. b) Es ist die Basis für Subnetting. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) 254 Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für 192.168.1.0/24?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Bereich"}, {"text": "Hostanzahl", "correct": false, "because": "Bestimmt Nutzung"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 192.168.1.255 die letzte Adresse bei /24?', 2, '[{"text": "Ja", "correct": true, "because": "Broadcastadresse"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetzmaske hat 192.168.1.0 mit 4 Subnetzen?', 4, '[{"text": "255.255.255.192", "correct": true, "because": "2 Bits geliehen, /26"}, {"text": "255.255.255.128", "correct": false, "because": "Nur 2 Subnetze"}, {"text": "255.255.255.0", "correct": false, "because": "Keine Aufteilung"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 192.168.1.0/24 keine Subnetze erlaubt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann aufgeteilt werden"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei 192.168.1.0/24 für Subnetting?', 3, '[{"text": "Hostbedarf", "correct": true, "because": "Bestimmt Subnetzgröße"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 192.168.1.0/24 ist Klasse C. b) Es hat 128 nutzbare Hosts.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) 254 Hosts"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Subnetze ergeben sich bei 192.168.1.0/24 mit /26?', 5, '[{"text": "192.168.1.0-192.168.1.63", "correct": true, "because": "Inkrement 64"}, {"text": "192.168.1.64-192.168.1.127", "correct": true, "because": "2. Subnetz"}, {"text": "192.168.1.128-192.168.1.191", "correct": true, "because": "3. Subnetz"}, {"text": "192.168.1.192-192.168.1.255", "correct": true, "because": "4. Subnetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei 192.168.1.0/24 unwichtig?', 3, '[{"text": "Netzwerkmaske", "correct": false, "because": "Definiert Bereich"}, {"text": "Adressanzahl", "correct": false, "because": "Bestimmt Kapazität"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat 192.168.1.0/24 ein Inkrement von 256?', 3, '[{"text": "Ja", "correct": true, "because": "2^(32-24) = 256"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 192.168.1.0/24 privat ist?', 2, '[{"text": "Ja", "correct": true, "because": "192.168-Bereich ist privat"}, {"text": "Nein", "correct": false, "because": "Falsche Einordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Netzwerkadresse hat das 2. Subnetz bei 192.168.1.0/24 mit /25?', 4, '[{"text": "192.168.1.128", "correct": true, "because": "Inkrement 128"}, {"text": "192.168.1.64", "correct": false, "because": "Für /26"}, {"text": "192.168.1.255", "correct": false, "because": "Broadcast"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen bei 192.168.1.0/24 mit /27?', 3, '[{"text": "8", "correct": true, "because": "2^(27-24) = 8"}, {"text": "4", "correct": false, "because": "Für /26"}, {"text": "16", "correct": false, "because": "Für /28"}]');
